-- Objetivos por etapa (bola roja / naranja / verde) y seguimiento por alumno.
-- Basado en tenisXetapas (RFET). Idempotente: en producción las tablas y el catálogo
-- ya se crearon a mano, así que esta migración no hace nada si ya existen.
-- La app accede con Drizzle (conexión directa); sin políticas, la API pública de Supabase no ve las tablas.
CREATE TABLE IF NOT EXISTS "tennis_objectives" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"code" text NOT NULL UNIQUE,
	"sport" text DEFAULT 'tenis' NOT NULL,
	"ball" text NOT NULL CHECK ("ball" IN ('roja','naranja','verde')),
	"stage" text NOT NULL,
	"age_range" text NOT NULL,
	"aspect" text NOT NULL CHECK ("aspect" IN ('tecnico','tactico','mental','fisico')),
	"block" text NOT NULL,
	"title" text NOT NULL,
	"criterion" text,
	"source" text DEFAULT 'desglose' NOT NULL CHECK ("source" IN ('rfet','desglose','propio')),
	"sort_order" integer DEFAULT 0 NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"created_by" uuid REFERENCES "users"("id") ON DELETE set null,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "tennis_objectives_ball_aspect_idx" ON "tennis_objectives" ("ball","aspect","sort_order");--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "student_objectives" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"student_id" uuid NOT NULL REFERENCES "students"("id") ON DELETE cascade,
	"objective_id" uuid NOT NULL REFERENCES "tennis_objectives"("id") ON DELETE cascade,
	"achieved" boolean DEFAULT true NOT NULL,
	"achieved_at" timestamp with time zone DEFAULT now() NOT NULL,
	"marked_by" uuid REFERENCES "users"("id") ON DELETE set null,
	"notes" text,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	UNIQUE ("student_id","objective_id")
);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "student_objectives_student_idx" ON "student_objectives" ("student_id");--> statement-breakpoint
ALTER TABLE "tennis_objectives" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "student_objectives" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
on conflict (code) do nothing;
